# -*- coding: utf-8 -*-

from odoo import models, fields, api, _
from odoo.exceptions import UserError
import base64
import io
import gzip
import logging

_logger = logging.getLogger(__name__)

try:
    from reportlab.pdfgen import canvas
    from reportlab.lib.utils import ImageReader
    from reportlab.graphics.barcode import code128
    from reportlab.lib import colors
    from pypdf import PdfReader, PdfWriter
    HAS_PDF = True
except ImportError:
    HAS_PDF = False

# This is the vector PDF produced directly from OMR.drawio.xml.
# It is embedded so the Odoo renderer uses the exact same geometry every time.
_TEMPLATE_GZ_B64 = r"""

"""

class OMRSheet(models.Model):
    _name = 'exam.omr.sheet'
    _description = 'Student OMR Sheet'
    _inherit = ['mail.thread', 'mail.activity.mixin']
    _order = 'serial_number'
    # Exact page size of the vector PDF generated from OMR.drawio.xml.
    # These are CLASS constants; never assign to self.PAGE_W/self.PAGE_H in Odoo.
    PAGE_W = 446.4567
    PAGE_H = 631.41735

    name = fields.Char(string='Reference', compute='_compute_name', store=True)
    serial_number = fields.Char(string='SI No.', required=True, copy=False, default=lambda self: self.env['ir.sequence'].next_by_code('exam.omr.sheet') or 'NEW')

    student_id = fields.Many2one('student.student', string='Student', required=True, tracking=True, index=True)
    registration_number = fields.Char(related='student_id.registration_number', string='Registration Number', store=True)
    student_name = fields.Char(related='student_id.name', string='Student Name', store=True)
    student_photo = fields.Binary(related='student_id.student_photo', string='Photo')
    hall_ticket_number = fields.Char(string='Hall Ticket No.', compute='_compute_hall_ticket_number', store=True)

    program_id = fields.Many2one(related='student_id.program_id', store=True)
    department_id = fields.Many2one(related='student_id.department_id', store=True)
    branch_name = fields.Char(string='Branch', compute='_compute_branch', store=True)

    examination_id = fields.Many2one('examination.examination', string='Examination', required=True, tracking=True, index=True)
    exam_month_year = fields.Char(string='Month-Year')
    exam_date = fields.Date(string='Date of Exam')

    subject_id = fields.Many2one('university.subject', string='Subject', required=True, tracking=True, index=True)
    subject_code = fields.Char(related='subject_id.code', string='Sub Code', store=True)
    subject_name = fields.Char(related='subject_id.name', string='Sub Name', store=True)

    omr_template_id = fields.Many2one('exam.omr.template', string='OMR Template', required=True, tracking=True)

    barcode_data = fields.Char(string='Barcode Data', compute='_compute_barcode_data', store=True)
    barcode_image = fields.Binary(string='Barcode Image', compute='_compute_barcode_image', store=True)

    omr_pdf = fields.Binary(string='OMR Sheet PDF', attachment=True)
    omr_pdf_filename = fields.Char(string='PDF Filename')

    state = fields.Selection([
        ('draft', 'Draft'), ('generated', 'Generated'), ('downloaded', 'Downloaded'),
        ('attached', 'Attached to Booklet'), ('scanned', 'Scanned')
    ], string='Status', default='draft', tracking=True)
    download_count = fields.Integer(default=0)
    company_id = fields.Many2one('res.company', default=lambda s: s.env.company)

    _sql_constraints = [
        ('unique_student_exam_subject', 'unique(student_id, examination_id, subject_id)',
         'OMR sheet already exists for this student, exam, and subject!'),
    ]

    @api.depends('student_id', 'subject_id', 'serial_number')
    def _compute_name(self):
        for rec in self:
            parts = [rec.serial_number or '']
            if rec.student_id:
                parts.append(rec.student_id.registration_number or rec.student_id.name or '')
            if rec.subject_id:
                parts.append(rec.subject_id.code or '')
            rec.name = ' - '.join(filter(None, parts))

    @api.depends('department_id')
    def _compute_branch(self):
        for rec in self:
            rec.branch_name = rec.department_id.name if rec.department_id else ''

    @api.depends('student_id', 'examination_id')
    def _compute_hall_ticket_number(self):
        for rec in self:
            hall_ticket = False
            if rec.student_id and rec.examination_id:
                hall_ticket = self.env['examination.hall.ticket'].search([
                    ('student_id', '=', rec.student_id.id),
                    ('examination_id', '=', rec.examination_id.id),
                ], limit=1)
            rec.hall_ticket_number = hall_ticket.name if hall_ticket else ''

    @api.depends('student_id', 'examination_id', 'subject_id', 'serial_number')
    def _compute_barcode_data(self):
        for rec in self:
            rec.barcode_data = rec.serial_number if (rec.student_id and rec.examination_id and rec.subject_id) else False

    @api.depends('barcode_data')
    def _compute_barcode_image(self):
        for rec in self:
            rec.barcode_image = False
            if not rec.barcode_data or not HAS_PDF:
                continue
            try:
                from reportlab.graphics import renderPM
                drawing = code128.Code128(rec.barcode_data, barHeight=9, humanReadable=False)
                buf = io.BytesIO()
                renderPM.drawToFile(drawing, buf, fmt='PNG')
                rec.barcode_image = base64.b64encode(buf.getvalue())
            except Exception:
                pass

    def action_generate_pdf(self):
        self.ensure_one()
        if not HAS_PDF:
            raise UserError(_('pypdf and reportlab are required to generate the OMR PDF.'))
        pdf_data = self._render_omr_pdf()
        filename = f"OMR_{self.serial_number}_{self.registration_number or 'REG'}.pdf"
        self.write({'omr_pdf': base64.b64encode(pdf_data), 'omr_pdf_filename': filename, 'state': 'generated'})
        return True

    def action_download(self):
        self.ensure_one()
        if not self.omr_pdf:
            self.action_generate_pdf()
        self.write({'download_count': self.download_count + 1, 'state': 'downloaded'})
        return {'type': 'ir.actions.act_url', 'url': f'/web/content?model=exam.omr.sheet&id={self.id}&field=omr_pdf&filename_field=omr_pdf_filename&download=true', 'target': 'self'}

    def action_mark_attached(self):
        self.write({'state': 'attached'})

    def action_reset_draft(self):
        self.write({'state': 'draft'})

    # ------------------------------------------------------------------
    # Exact XML-template renderer
    # ------------------------------------------------------------------
    def _template_pdf(self):
        raw = gzip.decompress(base64.b64decode(_TEMPLATE_GZ_B64))
        return PdfReader(io.BytesIO(raw))

    @staticmethod
    def _pdf_y(page_h, top_y, height=0):
        # Draw using reportlab's bottom-left coordinate system while the
        # reference template coordinates used by the extracted PDF are top-left.
        return page_h - top_y - height

    def _draw_text(self, c, x, top_y, text, size=6.0, bold=False, max_width=None):
        if not text:
            return
        font = 'Helvetica-Bold' if bold else 'Helvetica'
        c.setFont(font, size)
        s = str(text)
        if max_width:
            while len(s) > 1 and c.stringWidth(s, font, size) > max_width:
                s = s[:-1]
            if s != str(text):
                s = s[:-1] + '…'
        c.drawString(x, self.PAGE_H - top_y - size + 1, s)

    def _draw_center(self, c, x, top_y, text, size=6.0, bold=False):
        if not text:
            return
        font = 'Helvetica-Bold' if bold else 'Helvetica'
        c.setFont(font, size)
        c.drawCentredString(x, self.PAGE_H - top_y - size + 1, str(text))

    def _draw_barcode(self, c, x, top_y, w, h):
        if not self.barcode_data:
            return
        try:
            # Hide the template's placeholder word without disturbing its border.
            c.setFillColor(colors.white)
            c.rect(x + 1, self.PAGE_H - top_y - h + 1, w - 2, h - 2, fill=1, stroke=0)
            probe = code128.Code128(str(self.barcode_data), barWidth=1, barHeight=h - 4, humanReadable=False)
            bw = (w - 10) / probe.width if probe.width else 1
            obj = code128.Code128(str(self.barcode_data), barWidth=bw, barHeight=h - 4, humanReadable=False)
            c.setFillColor(colors.black)
            obj.drawOn(c, x + 5, self.PAGE_H - top_y - h + 2)
        except Exception as exc:
            _logger.warning('Barcode render failed: %s', exc)

    def _draw_photo(self, c, x, top_y, w, h):
        # White out the placeholder text only; preserve the original border.
        y = self.PAGE_H - top_y - h
        c.setFillColor(colors.white)
        c.rect(x + .5, y + .5, w - 1, h - 1, fill=1, stroke=0)
        if self.student_photo:
            try:
                img = ImageReader(io.BytesIO(base64.b64decode(self.student_photo)))
                c.drawImage(img, x + 1, y + 1, width=w - 2, height=h - 2, preserveAspectRatio=True, anchor='c', mask='auto')
            except Exception as exc:
                _logger.warning('Student photo render failed: %s', exc)
        c.setStrokeColor(colors.black)
        c.rect(x, y, w, h, fill=0, stroke=1)
        c.setFillColor(colors.black)

    def _draw_top_dynamic(self, c):
        # Coordinates are taken from the exact PDF created from OMR.drawio.xml.
        self._draw_text(c, 125.5, 72.8, self.serial_number, 6.5, bold=True)
        self._draw_barcode(c, 118.7, 79.6, 109.0, 16.2)
        self._draw_photo(c, 231.7, 63.5, 28.2, 32.3)

        vals = [
            self.hall_ticket_number or '', self.student_name or '',
            self.examination_id.name or '', self.exam_month_year or '',
            self.branch_name or '', self.subject_code or '',
            self.subject_name or '', str(self.exam_date) if self.exam_date else '',
        ]
        tops = [104.8, 116.9, 129.0, 143.2, 157.3, 171.4, 185.5, 199.7]
        for top, val in zip(tops, vals):
            self._draw_text(c, 143.5, top, val, 5.8, max_width=128)

    def _draw_section_dynamic(self, c, barcode_top, value_tops):
        # Exact coordinates taken from the vector PDF generated from the
        # supplied OMR.drawio.xml.  Only the data changes; every border, grid,
        # bubble and label remains the original template geometry.
        self._draw_barcode(c, 179.2, barcode_top, 109.0, 16.2)
        vals = [
            self.examination_id.name or '', self.exam_month_year or '',
            self.branch_name or '', self.subject_code or '',
            self.subject_name or '', str(self.exam_date) if self.exam_date else '',
        ]
        for top, val in zip(value_tops, vals):
            self._draw_text(c, 126.8, top, val, 4.0, max_width=48)

    def _render_omr_pdf(self):
        reader = self._template_pdf()
        template_page = reader.pages[0]
        page_w = float(template_page.mediabox.width)
        page_h = float(template_page.mediabox.height)

        # The template is the source of truth. Do not write page dimensions
        # onto the Odoo record (Odoo model records use restricted attributes).
        if abs(page_w - self.PAGE_W) > 0.01 or abs(page_h - self.PAGE_H) > 0.01:
            raise UserError(_(
                'The embedded OMR template has an unexpected page size: %.2f x %.2f pt.'
            ) % (page_w, page_h))

        overlay_buf = io.BytesIO()
        c = canvas.Canvas(overlay_buf, pagesize=(page_w, page_h))
        self._draw_top_dynamic(c)
        # The reference template has Part-III beginning around y=239 and
        # Part-II around y=440. These are deliberately fixed: the geometry
        # must never move when student data changes.
        self._draw_section_dynamic(c, 249.1, [251.1, 263.2, 277.0, 290.5, 299.6, 313.8])
        self._draw_section_dynamic(c, 450.9, [452.9, 467.0, 479.1, 491.2, 503.4, 515.6])
        c.save()

        overlay = PdfReader(io.BytesIO(overlay_buf.getvalue())).pages[0]
        template_page.merge_page(overlay)
        writer = PdfWriter()
        writer.add_page(template_page)
        out = io.BytesIO()
        writer.write(out)
        return out.getvalue()